sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  c.newAssignment = { role: "", user_id: "" };
  c.roles = [
    { value: "application_owner", label: "Application Owner" },
    { value: "it_custodian", label: "IT Custodian" },
    { value: "audit_owner", label: "Audit Owner" },
    { value: "program_manager", label: "Program Manager" },
    { value: "developer", label: "Developer" }
  ];

  $scope.$on("application.created", function(event, params) {
    c.data.applicationId = params.app_id;
  });

  c.assignUser = function() {
    if (!c.data.applicationId || !c.newAssignment.role || !c.newAssignment.user_id) return;

    c.server.get({
      action: "assign",
      app_id: c.data.applicationId,
      role: c.newAssignment.role,
      user_id: c.newAssignment.user_id
    }).then(function(r) {
      c.data.assignments = r.data.assignments;
      c.newAssignment = { role: "", user_id: "" };
    });
  };

  c.removeAssignment = function(assignment) {
    c.server.get({
      action: "remove",
      assignment_id: assignment.sys_id
    }).then(function(r) {
      c.data.assignments = r.data.assignments;
    });
  };
};

sp_widget.css:
.ibar-assignment-panel {
  padding: 20px;
}
.ibar-assignment-panel .section-title {
  margin-bottom: 16px;
  font-size: 16px;
  font-weight: 600;
}
.ibar-assignment-panel .assign-form {
  margin-top: 16px;
  padding: 12px;
  background: #f9f9f9;
  border-radius: 4px;
}

sp_widget.script:
(function() {
  data.assignments = [];
  data.message = "";
  data.applicationId = input && input.app_id ? input.app_id : ($sp.getParameter("app_id") || "");

  try {
    if (input && input.action === "assign") {
      assignUser(input);
      return;
    }
    if (input && input.action === "remove") {
      removeAssignment(input.assignment_id);
      return;
    }

    if (data.applicationId) {
      loadAssignments(data.applicationId);
    }
  } catch (e) {
    gs.error("IBAR User Assignment Panel error: " + e.message);
    data.message = "An error occurred.";
  }

  function loadAssignments(appId) {
    var gr = new GlideRecord("x_1433041_identi_0_assignment");
    gr.addQuery("application", appId);
    gr.addQuery("active", true);
    gr.query();
    while (gr.next()) {
      var userName = "";
      var userGr = new GlideRecord("sys_user");
      if (userGr.get(gr.getValue("user"))) {
        userName = userGr.getValue("name");
      }
      data.assignments.push({
        sys_id: gr.getUniqueValue(),
        role: gr.getValue("role"),
        role_display: gr.getDisplayValue("role"),
        user_id: gr.getValue("user"),
        user_name: userName,
        assigned_at: gr.getDisplayValue("assigned_at")
      });
    }
  }

  function assignUser(params) {
    var existing = new GlideRecord("x_1433041_identi_0_assignment");
    existing.addQuery("application", params.app_id);
    existing.addQuery("role", params.role);
    existing.addQuery("active", true);
    existing.query();
    while (existing.next()) {
      existing.setValue("active", false);
      existing.update();
    }

    var gr = new GlideRecord("x_1433041_identi_0_assignment");
    gr.initialize();
    gr.setValue("application", params.app_id);
    gr.setValue("user", params.user_id);
    gr.setValue("role", params.role);
    gr.setValue("active", true);
    gr.setValue("assigned_at", new GlideDateTime().getDisplayValue());
    gr.setValue("assigned_by", gs.getUserID());
    gr.insert();

    if (params.role === "application_owner") {
      var appGr = new GlideRecord("x_1433041_identi_0_application");
      if (appGr.get(params.app_id)) {
        appGr.setValue("assigned_owner", params.user_id);
        appGr.update();
      }
    }

    data.applicationId = params.app_id;
    loadAssignments(params.app_id);
    data.message = "User assigned successfully.";
  }

  function removeAssignment(assignmentId) {
    var gr = new GlideRecord("x_1433041_identi_0_assignment");
    if (gr.get(assignmentId)) {
      var appId = gr.getValue("application");
      gr.setValue("active", false);
      gr.update();
      data.applicationId = appId;
      loadAssignments(appId);
      data.message = "Assignment removed.";
    }
  }
})();
